<template>
  <section class="boards-manager" :aria-busy="busy">
    <header class="manager-head">
      <div><span class="eyebrow">监控大屏 · 编辑工作区</span><h1>大屏编辑</h1><p>从一个模板开始，让数据各就其位。</p></div>
      <button class="return-button" :disabled="busy" @click="returnToScreen"><span aria-hidden="true">←</span> 返回监控大屏</button>
    </header>
    <div v-if="error" class="notice error" role="alert"><span>{{ error }}</span><button :disabled="busy" @click="reload">重新加载</button></div>
    <div v-if="message" class="notice success" role="status"><span aria-hidden="true">✓</span> {{ message }}</div>
    <nav class="manager-tabs" aria-label="大屏编辑页签"><button v-for="t in tabs" :key="t.key" :aria-pressed="tab===t.key" :class="{active:tab===t.key}" :disabled="busy" @click="tab=t.key">{{ t.label }}</button><span class="workspace-hint">草稿独立保存 · 发布后生效</span></nav>
    <template v-if="!draft">
      <div class="list-toolbar"><div><h2>{{ tab==='templates'?'选择适合你的布局':'我的大屏' }}</h2><p>{{ tab==='templates'?'主题与布局一并应用，内容仍可自由调整。':`${boards.length} 个大屏 · ${defaultId?'已使用自定义默认大屏':'当前使用系统默认大屏'}` }}</p></div><div class="list-actions"><input v-model="search" type="search" aria-label="搜索大屏" placeholder="搜索大屏名称" /><button :disabled="busy||!defaultId" :title="defaultId?'切换回系统监控模板':'当前已使用系统默认大屏'" @click="resetDefault">恢复系统默认</button><button class="primary" :disabled="busy||!builtin" @click="create()">＋ 新建大屏</button></div></div>
      <p v-if="loading" class="empty" role="status">正在读取大屏…</p>
      <div v-else class="board-cards">
        <article v-for="preset in tab==='templates'&&builtin?boardTemplates.filter(p=>p.name.includes(search)):[]" :key="preset.key" class="board-card preset-card">
          <div class="preset-preview" :style="themeVariables({...themes[preset.theme],font_size:13,radius:12})"><span v-for="(type,index) in preset.types.slice(0,6)" :key="type" :class="{'preview-wide':index===0}"><i></i>{{ widgetLabels[type] }}</span></div>
          <div class="card-content"><div class="card-badges"><span class="badge">场景模板</span><span class="theme-caption">{{ themes[preset.theme].name }}</span></div><h2>{{ preset.name }}</h2><p>{{ preset.description }}</p><footer><span>{{ preset.types.length }} 个组件</span><button class="primary" :disabled="busy" @click="createPreset(preset)">使用此样式 <span aria-hidden="true">→</span></button></footer></div>
        </article>
        <article v-if="tab==='templates'&&builtin" class="board-card builtin"><div class="card-content"><span class="badge">系统模板</span><h2>{{ builtin.name }}</h2><p>状态总览、主机资源、K3s、告警和历史图表。</p><footer><span>5 个监控组件</span><button :disabled="busy" @click="create(builtin)">使用模板</button></footer></div></article>
        <article v-for="item in visibleBoards" :key="item.id" class="board-card" :class="{'is-default':item.id===defaultId}">
          <div class="saved-preview" :style="themeVariables(item.config.theme)"><span class="preview-dots"><i></i><i></i><i></i></span><strong>{{ item.config.title }}</strong><div><span v-for="widget in item.config.widgets.slice(0,4)" :key="widget.id">{{ widget.title||widgetLabels[widget.type] }}</span></div></div>
          <div class="card-content"><div class="card-badges"><span v-if="item.id===defaultId" class="badge default-badge">当前默认</span><span class="badge quiet">{{ item.published_version ? `已发布 v${item.published_version}` : '未发布草稿' }}</span><span v-if="item.is_template" class="badge quiet">自定义模板</span></div>
          <h2>{{ item.name }}</h2><p>{{ item.config.widgets.length }} 个组件 · 更新于 {{ formatTime(item.updated_at) }}</p>
          <div class="card-main-actions"><button class="primary" :disabled="busy" @click="edit(item.id)">编辑</button><button :disabled="busy" @click="previewPublished(item)">预览</button><button :disabled="busy||!item.published_version||item.id===defaultId" :title="!item.published_version?'请先发布大屏':item.id===defaultId?'当前正在使用此大屏':''" @click="makeDefault(item)">设为默认</button></div>
          <div class="card-actions"><button class="text-button" :disabled="busy" @click="create(item)">复制大屏</button><button class="text-button" :disabled="busy" @click="showHistory(item)">版本记录</button><button class="text-button danger" :disabled="busy||item.id===defaultId" :title="item.id===defaultId?'切换默认大屏后才可删除':''" @click="removeBoard(item)">删除</button></div></div>
        </article>
      </div>
      <div v-if="!loading&&!visibleBoards.length&&tab==='boards'" class="empty"><strong>{{ search?'没有匹配的大屏':'创建你的第一个大屏' }}</strong><p>{{ search?'试试其他名称，或清空搜索。':'选择场景模板快速开始，也可以从系统监控布局自由编辑。' }}</p><button v-if="!search" @click="tab='templates'">浏览场景模板 →</button></div>
    </template>
    <template v-else>
      <div class="editor-toolbar"><div class="editor-identity"><button :disabled="busy" @click="closeEditor">← 返回列表</button><label class="name-field"><span>大屏名称</span><input v-model="draft.name" :disabled="busy" maxlength="80" aria-label="大屏名称" /></label><span class="save-state" :class="{unsaved:dirty}"><i></i>{{ busy?'正在处理…':dirty?'有未保存修改':'草稿已保存' }}<small>r{{ draft.revision }}</small></span></div><div class="editor-actions"><button :disabled="busy" @click="save">保存草稿</button><button :disabled="busy||!draft.config.widgets.length" @click="previewDraft">预览草稿</button><button v-if="draft.published_version&&defaultId!==draft.id" :disabled="busy||dirty" title="将已发布版本设为当前监控大屏" @click="makeDefault(draft)">设为默认</button><button class="primary" :disabled="busy||!draft.config.widgets.length" @click="publish">发布</button></div></div>
      <div class="editor-layout" :inert="busy || !!preview || !!history">
        <aside class="component-library">
          <nav class="library-tabs" aria-label="素材选项"><button :class="{active:libraryTab==='components'}" :aria-pressed="libraryTab==='components'" @click="libraryTab='components'">组件</button><button :class="{active:libraryTab==='themes'}" :aria-pressed="libraryTab==='themes'" @click="libraryTab='themes'">主题</button></nav>
          <template v-if="libraryTab==='components'"><input v-model="componentSearch" type="search" aria-label="搜索组件" placeholder="搜索组件" /><p class="library-help">点击添加 · {{ draft.config.widgets.length }}/30</p><section v-for="group in componentGroups" :key="group.name" class="library-group"><h2>{{ group.name }}</h2><button v-for="type in group.types" :key="type" :disabled="draft.config.widgets.length>=30" @click="addWidget(type)"><span aria-hidden="true">＋</span> {{ widgetLabels[type] }}</button></section><p v-if="!componentGroups.length" class="hint">没有找到组件</p></template>
          <template v-else><h2 class="library-title">选择配色</h2><p class="library-help">仅调整当前草稿</p><button v-for="(theme,key) in themes" :key="key" class="theme-choice" :class="{chosen:themeActive(theme)}" :aria-pressed="themeActive(theme)" @click="applyTheme(theme)"><i :style="{background:theme.background,borderColor:theme.accent}"></i><span>{{ theme.name }}</span><b v-if="themeActive(theme)" aria-hidden="true">✓</b></button></template>
        </aside>
        <div class="editor-canvas"><div class="canvas-caption"><span>画布预览</span><span>拖动六点手柄移动 · 拖动右下角缩放</span></div><ScreenCanvas :key="canvasKey" :config="draft.config" :suspended="!!preview" editable :selected-id="selectedId" @select="selectedId=$event" @remove="removeWidget" @layout="updateLayout" /><p v-if="!draft.config.widgets.length" class="empty">从左侧添加第一个组件</p></div>
        <aside class="property-panel"><section class="property-section"><h2>大屏设置</h2><label>大屏标题<input v-model="draft.config.title" maxlength="80" /></label><label class="checkbox"><input v-model="draft.is_template" type="checkbox" />保存为可复用模板</label><div class="color-grid"><label v-for="field in colorFields" :key="field.key">{{ field.label }}<span class="color-control"><input v-model="draft.config.theme[field.key]" type="color" /><code>{{ draft.config.theme[field.key] }}</code></span></label></div><label>面板风格<select v-model="draft.config.theme.style" aria-label="面板风格"><option v-for="(label,key) in panelStyles" :key="key" :value="key">{{ label }}</option></select></label><div class="property-pair"><label>字号<input v-model.number="draft.config.theme.font_size" type="number" min="12" max="20" /></label><label>圆角<input v-model.number="draft.config.theme.radius" type="number" min="0" max="24" /></label></div></section>
          <section v-if="selected" class="property-section"><h2>组件属性 <small>{{ widgetLabels[selected.type] }}</small></h2><label>标题<input v-model="selected.title" maxlength="80" /></label><label>展示样式<select v-model="selected.variant" aria-label="展示样式"><option v-for="(label,key) in widgetVariants" :key="key" :value="key">{{ label }}</option></select></label><label>组件强调色<span class="color-control"><input :value="selected.accent||draft.config.theme.accent" type="color" @input="selected.accent=$event.target.value" /><code>{{ selected.accent||'跟随主题' }}</code></span></label><button v-if="selected.accent" class="text-button" @click="selected.accent=null">恢复主题颜色</button><label v-if="selected.type==='text'">内容<textarea v-model="selected.text" maxlength="4000" rows="5" /></label><div class="property-pair"><label v-for="field in geometryFields" :key="field.key">{{ field.label }}<input :value="selected[field.key]" type="number" :min="field.min" :max="field.max" @change="positionWidget(field.key,$event)" /></label></div><p class="hint">位置和尺寸按12列网格计算。</p><div class="widget-actions"><button :disabled="draft.config.widgets.length>=30" @click="duplicateWidget">复制组件</button><button class="danger" @click="removeWidget(selected.id)">移除组件</button></div></section><p v-else class="hint selection-hint">点击画布中的组件，编辑样式和尺寸。</p>
        </aside>
      </div>
    </template>
    <div v-if="preview" class="preview-overlay" role="dialog" aria-modal="true" aria-label="大屏预览" tabindex="-1" @keydown="dialogKeys"><header><div><strong>{{ preview.label }}</strong><span>预览不会改变当前默认大屏</span></div><button @click="preview=null">关闭预览 <span aria-hidden="true">×</span></button></header><ScreenCanvas :config="preview.config" preview-mode /></div>
    <div v-if="history" class="modal-backdrop" @click.self="history=null"><section class="history-dialog" role="dialog" aria-modal="true" aria-label="发布记录" tabindex="-1" @keydown="dialogKeys"><header><div><h2>{{ history.board.name }}</h2><p>发布记录</p></div><button aria-label="关闭发布记录" @click="history=null">关闭 ×</button></header><p class="hint">恢复后先进入草稿，预览并重新发布后生效。</p><p v-if="!history.items.length" class="empty">还没有发布版本，完成编辑后点击“发布”。</p><article v-for="version in history.items" :key="version.version"><div><strong>v{{ version.version }} · {{ version.name }}</strong><small>{{ formatTime(version.created_at) }}</small></div><button :disabled="busy" @click="previewVersion(history.board.id,version.version)">预览</button><button class="primary" :disabled="busy" @click="restore(history.board.id,version.version)">恢复到草稿</button></article></section></div>
    <div v-if="confirmation" class="modal-backdrop confirmation-backdrop" @click.self="finishConfirmation(false)"><section class="confirmation-dialog" role="alertdialog" aria-modal="true" aria-labelledby="screen-confirm-title" aria-describedby="screen-confirm-message" tabindex="-1" @keydown="dialogKeys"><span class="confirmation-icon" :class="{danger:confirmation.danger}" aria-hidden="true">{{ confirmation.danger?'!':'↶' }}</span><h2 id="screen-confirm-title">{{ confirmation.title }}</h2><p id="screen-confirm-message">{{ confirmation.message }}</p><footer><button @click="finishConfirmation(false)">{{ confirmation.cancelLabel||'取消' }}</button><button :class="confirmation.danger?'danger-solid':'primary'" @click="finishConfirmation(true)">{{ confirmation.confirmLabel||'确认' }}</button></footer></section></div>
  </section>
</template>
<script setup>
import {computed,onMounted,onBeforeUnmount,ref,watch,nextTick} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRoute,useRouter} from 'vue-router'
const route=useRoute(),router=useRouter()
import {api} from '../api'
import ScreenCanvas from './ScreenCanvas.vue'
import {widgetLabels,themes,clone,newWidget,applyLayout,panelStyles,widgetVariants,boardTemplates,templateConfig,themeVariables} from '../utils/screenBoards.js'
const libraryTab=ref('components'),componentSearch=ref('')
const componentGroups=computed(()=>[
 {name:'基础监控',types:['overview','hosts','cluster','alerts','charts','text']},
 {name:'业务与运维',types:['logs','services','automation','usage','oss','opencode','sms','password','modules']},
 {name:'生活与能源',types:['electricity','subscriptions','inventory','tasks']},
].map(group=>({...group,types:group.types.filter(type=>widgetLabels[type].toLowerCase().includes(componentSearch.value.toLowerCase()))})).filter(group=>group.types.length))
function themeActive(theme){return ['background','surface','text','accent','style'].every(key=>(draft.value.config.theme[key]||'classic')===theme[key])}
function returnToScreen(){if(!busy.value)router.push({path:route.path})}
const tabs=[{key:'boards',label:'我的大屏'},{key:'templates',label:'模板与主题'}]
const colorFields=[{key:'background',label:'背景色'},{key:'surface',label:'面板色'},{key:'text',label:'文字色'},{key:'accent',label:'强调色'}]
const geometryFields=[{key:'x',label:'横向位置',min:0,max:10},{key:'y',label:'纵向位置',min:0,max:500},{key:'w',label:'宽度',min:2,max:12},{key:'h',label:'高度',min:2,max:30}]
const boards=ref([]),builtin=ref(null),defaultId=ref(null),loading=ref(true),busy=ref(false),error=ref(''),message=ref(''),tab=ref(route.query.panel==='templates'?'templates':'boards'),search=ref('')
const draft=ref(null),baseline=ref(''),selectedId=ref(''),canvasKey=ref(0),preview=ref(null),history=ref(null)
const snapshot=()=>draft.value?JSON.stringify({name:draft.value.name,config:draft.value.config,is_template:draft.value.is_template}):''
const dirty=computed(()=>!!draft.value&&snapshot()!==baseline.value)
const selected=computed(()=>draft.value?.config.widgets.find(w=>w.id===selectedId.value))
const visibleBoards=computed(()=>boards.value.filter(b=>(tab.value!=='templates'||b.is_template)&&b.name.toLowerCase().includes(search.value.toLowerCase())))
function formatTime(value){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'—'}
const confirmation=ref(null)
let confirmResolve=null
function askConfirmation(options){
  if(confirmResolve)return Promise.resolve(false)
  confirmation.value=options
  return new Promise(resolve=>{confirmResolve=resolve})
}
function finishConfirmation(accepted){const resolve=confirmResolve;confirmResolve=null;confirmation.value=null;resolve?.(accepted)}
function canLeave(){return !dirty.value||askConfirmation({title:'有未保存的修改',message:'离开后，本次未保存的修改将被放弃。已保存的草稿会保留。',confirmLabel:'放弃修改',cancelLabel:'继续编辑',danger:true})}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){loading.value=true;try{const data=await api.get('/screen-boards');boards.value=data.items;builtin.value=data.builtin;defaultId.value=data.default_id}finally{loading.value=false}}
async function reload(){if(!await canLeave())return;await run(async()=>{if(draft.value)await openDraft(draft.value.id);await load()})}
function acceptDraft(data){draft.value=clone(data);draft.value.config.theme.style??='classic';for(const w of draft.value.config.widgets){w.variant??='detail';w.accent??=null}baseline.value=snapshot();selectedId.value=draft.value.config.widgets[0]?.id||'';canvasKey.value++}
async function openDraft(id){acceptDraft(await api.get(`/screen-boards/${id}`))}
async function edit(id){if(!await canLeave())return;await run(()=>openDraft(id))}
async function create(source){if(!await canLeave())return;await run(async()=>{const config=clone(source?.config||builtin.value.config);const name=source?`${source.name.slice(0,70)} 副本`:'新建大屏';const data=await api.post('/screen-boards',{name,config,is_template:false});acceptDraft(data);tab.value='boards';await load()})}
async function createPreset(preset){await create({name:preset.name,config:templateConfig(preset,builtin.value.config)})}
async function saveDraft(){
  if(!draft.value.name.trim()||!draft.value.config.title.trim())throw new Error('请填写大屏名称和标题')
  const d=draft.value;const data=await api.put(`/screen-boards/${d.id}`,{name:d.name,config:d.config,is_template:d.is_template,revision:d.revision})
  draft.value.revision=data.revision;draft.value.updated_at=data.updated_at;baseline.value=snapshot();return data
}
async function save(){await run(async()=>{await saveDraft();await load();message.value='草稿已保存。预览确认后，点击发布使修改生效。'})}
async function publish(){await run(async()=>{if(dirty.value)await saveDraft();const d=draft.value;const data=await api.post(`/screen-boards/${d.id}/publish`,{revision:d.revision});acceptDraft(data);message.value=`已发布 v${data.published_version}。${defaultId.value===d.id?'当前默认大屏已更新。':'可返回列表设为默认大屏。'}`;await load()})}
async function makeDefault(item){await run(async()=>{await api.post('/screen-boards/default',{board_id:item.id});await load();message.value='默认大屏已切换。返回监控大屏即可查看。'})}
async function resetDefault(){await run(async()=>{await api.post('/screen-boards/default',{board_id:null});message.value='已切换为系统默认大屏。';await load()})}
async function closeEditor(){if(await canLeave()){draft.value=null;baseline.value='';message.value=''}}
function addWidget(type){const widget=newWidget(type,draft.value.config.widgets);if(widget.y+widget.h>500){error.value='画布高度已达到上限';return}draft.value.config.widgets.push(widget);selectedId.value=widget.id}
function removeWidget(id){draft.value.config.widgets=draft.value.config.widgets.filter(w=>w.id!==id);if(selectedId.value===id)selectedId.value=''}
function duplicateWidget(){if(draft.value.config.widgets.length>=30)return;const w={...clone(selected.value),id:newWidget(selected.value.type,[]).id,y:Math.max(0,...draft.value.config.widgets.map(w=>w.y+w.h))};if(w.y+w.h>500){error.value='画布高度已达到上限';return}draft.value.config.widgets.push(w);selectedId.value=w.id}
function updateLayout(layout){draft.value.config.widgets=applyLayout(draft.value.config.widgets,layout)}
function positionWidget(key,event){const number=Number(event.target.value),field=geometryFields.find(f=>f.key===key);if(!Number.isInteger(number)||number<field.min||number>field.max){event.target.value=selected.value[key];error.value=`${field.label}应为${field.min}至${field.max}的整数`;return}error.value='';const w=selected.value;w[key]=number;if(w.x+w.w>12)w.x=12-w.w}
function applyTheme(theme){const {name,...colors}=theme;Object.assign(draft.value.config.theme,colors)}
function previewDraft(){preview.value={label:'草稿预览 · 尚未发布',config:clone(draft.value.config)}}
async function previewVersion(id,version){await run(async()=>{const data=await api.get(`/screen-boards/${id}/versions/${version}`);preview.value={label:`发布版本 v${version}`,config:data.config}})}
async function previewPublished(item){if(item.published_version)await previewVersion(item.id,item.published_version);else preview.value={label:'草稿预览 · 尚未发布',config:clone(item.config)}}
async function showHistory(item){await run(async()=>{const data=await api.get(`/screen-boards/${item.id}/versions`);history.value={board:item,items:data.items}})}
async function restore(id,version){if(!await canLeave()||!await askConfirmation({title:`恢复 v${version}`,message:'将此版本恢复到草稿，当前已发布版本继续展示。预览后重新发布即可生效。',confirmLabel:'恢复到草稿'}))return;await run(async()=>{const current=await api.get(`/screen-boards/${id}`);const data=await api.post(`/screen-boards/${id}/versions/${version}/restore`,{revision:current.revision});acceptDraft(data);history.value=null;message.value=`已将 v${version} 恢复到草稿，请预览后发布。`;await load()})}
async function removeBoard(item){if(!await askConfirmation({title:'删除大屏',message:`确定删除“${item.name}”及其全部发布记录？此操作无法撤销。`,confirmLabel:'删除大屏',danger:true}))return;await run(async()=>{await api.del(`/screen-boards/${item.id}`,{query:{revision:item.revision}});await load()})}
function dialogKeys(e){
  if(e.key==='Escape'){if(confirmation.value)finishConfirmation(false);else if(preview.value)preview.value=null;else history.value=null;e.preventDefault();return}
  if(e.key!=='Tab')return
  const elements=[...e.currentTarget.querySelectorAll('button:not(:disabled),a[href],input,select,textarea')].filter(el=>el.getClientRects().length)
  const first=elements[0],last=elements.at(-1)
  if(e.shiftKey&&document.activeElement===first){last?.focus();e.preventDefault()}
  else if(!e.shiftKey&&document.activeElement===last){first?.focus();e.preventDefault()}
}
let returnFocus=null
watch(()=>confirmation.value?'confirmation':preview.value?'preview':history.value?'history':'',async open=>{
  if(open){if(!returnFocus)returnFocus=document.activeElement;await nextTick();document.querySelector('.confirmation-dialog button,.preview-overlay button,.history-dialog button')?.focus()}
  else {returnFocus?.focus();returnFocus=null}
})
function unload(e){if(dirty.value){e.preventDefault();e.returnValue=''}}
onBeforeRouteUpdate((to,from)=>to.query.edit!==from.query.edit?canLeave():true)
watch(()=>route.query.panel,value=>{if(!draft.value)tab.value=value==='templates'?'templates':'boards'})
onBeforeRouteLeave(()=>canLeave())
onMounted(()=>{run(load);window.addEventListener('beforeunload',unload)})
onBeforeUnmount(()=>{window.removeEventListener('beforeunload',unload);finishConfirmation(false)})
</script>

<style scoped>
.boards-manager{--studio-text:#243247;--studio-muted:#64748b;--studio-line:#dce3ed;--studio-primary:#245cce;padding:28px;background:#f4f6fa;color:var(--studio-text);min-height:100%;font-size:14px;line-height:1.5}
